    $ok($op->save_charge(array_replace($charge,['request_key'=>str_repeat('9',32),'line_reference'=>'LEGACY','amount'=>10,'existing_mutation_id'=>$legacyId]),1),'explicit legacy identification without double posting');
    $ok($purchase->apply_manual_account_mutation($fee4,1),'separate fee allowed after legacy identified');
