    $reconCharge=$ok($op->save_charge(array_replace($charge,['request_key'=>bin2hex(random_bytes(16)),'line_reference'=>'RECON-1','amount'=>$remainingFee]),1),'remaining reconciliation cost')['id'];
    $draft=$ok($revenue->save_line(['reconciliation_date'=>$today,'revenue_date'=>$today,'payment_method_id'=>1,'account_id'=>1,'actual_amount'=>$actual,'resolution_type'=>'OUT','report_category'=>'PLATFORM_FEE','settlement_control_id'=>$caseId,'settlement_charge_id'=>$reconCharge],1),'revenue draft with charge identity');
    $ok($revenue->post_line($draft['line_id'],1),'revenue writer posts only separate identified remaining fee');
