    $cashCharge=$ok($op->save_charge(array_replace($charge,['request_key'=>bin2hex(random_bytes(16)),'line_reference'=>'CASH-1','amount'=>5]),1),'cash reconciliation identity')['id'];
    $cash=$context->Finance_cash_reconciliation_model;
    $draft=$ok($cash->save_line(['reconciliation_date'=>$today,'account_id'=>1,'actual_balance'=>(string)($balance()-5),'resolution_type'=>'OUT','report_category'=>'PLATFORM_FEE','settlement_control_id'=>$caseId,'settlement_charge_id'=>$cashCharge],1),'cash recon draft identity');
    $ok($cash->post_line($draft['line']['id'],1),'cash writer posts distinct identified fee');
    $check($db->get_where('fin_account_mutation_log',['settlement_charge_id'=>$cashCharge])->num_rows()===1,'cash writer persists identity');
