    $ok($op->save_policy(['revision'=>$policy['revision'],'approval_enabled'=>1,'approval_threshold'=>50,'evidence_required'=>1,'payroll_day'=>25,'notes'=>'Test proof requirement'],1),'optional evidence policy enabled in fixture only');
    $largeId=$ok($op->save_charge(array_replace($charge,['request_key'=>bin2hex(random_bytes(16)),'line_reference'=>'LARGE-FEE','amount'=>10000]),1),'unfunded fee approval target')['id'];
